INSERT INTO `author` VALUES (1,'James Clear is the author of Atomic Habits and writes about habits, decision-making, and continuous improvement.','James Clear'),(2,'George Orwell was an English novelist and essayist, best known for his novels 1984 and Animal Farm.','George Orwell'),(4,'Shrinivas Navkar is a Marathi author known for his works that explore social issues, human emotions, and interpersonal relationships with depth and sensitivity.','Shrinivas Navkar'),(5,'Dr. Deepak Ranade is a neurosurgeon, thinker, and author whose writings explore the intersection of science, spirituality, consciousness, and self-realisation.','Dr. Deepak Ranade'),(6,'Paulo Coelho is a Brazilian author best known for his novel The Alchemist, a philosophical book about destiny, self-discovery, and following oneâ€™s dreams.','Paulo Coelho'),(7,'Kamlabai Prasann was a Marathi writer known for her reflective and philosophical writings focusing on life, values, and human emotions.','Kamlabai Prasann'),(8,'Aabhas Anand is a contemporary Marathi writer whose works explore existential themes, inner conflict, emotional solitude, and the human search for meaning.','Aabhas Anand');
